using System;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.Rendering;using UnityEngine.Rendering.HighDefinition;
public static class FinalFarmStyle {
 const string A="Assets/NewMap/FiveHangars";
 public static string Main(){var root=GameObject.Find("New_Map").transform;var exp=root.Find("11_Five_Hangar_Farm");var original=root.Find("01_Modular_Hangar/Tall timber hall with glazing");var primitive=GameObject.CreatePrimitive(PrimitiveType.Cube);var cube=primitive.GetComponent<MeshFilter>().sharedMesh;UnityEngine.Object.DestroyImmediate(primitive);
  foreach(var h in exp.Cast<Transform>().Where(t=>t.name.StartsWith("Hangar "))){int id=int.Parse(h.name.Substring(7,1));var shell=h.Find("Combined structure");var exterior=AssetDatabase.LoadAssetAtPath<Material>(A+"/Hangar "+id+" exterior.mat");Material roof=null;
   foreach(var renderer in shell.GetComponentsInChildren<MeshRenderer>()){var source=original.Find(renderer.name);if(!source)continue;renderer.sharedMaterials=source.GetComponent<MeshRenderer>().sharedMaterials.Select(m=>m.name.Contains(" red ")?exterior:m).ToArray();}
   var rr=shell.Find("Roof").GetComponent<MeshRenderer>();rr.sharedMaterials=rr.sharedMaterials.Select(m=>{if(!m.name.ToLowerInvariant().Contains("roof"))return m;if(!roof){roof=new Material(m){name="Hangar "+id+" roof finish"};roof.SetColor("_BaseColor",id==2?new Color(.38f,.24f,.15f):id==3?new Color(.34f,.4f,.43f):id==4?new Color(.15f,.18f,.2f):new Color(.25f,.32f,.26f));AssetDatabase.CreateAsset(roof,A+"/"+roof.name+".mat");}return roof;}).ToArray();
   if(id>=4){var ribMat=new Material(exterior){name="Hangar "+id+" metal ribs"};ribMat.SetFloat("_Metallic",.45f);ribMat.SetFloat("_Smoothness",.3f);HDMaterial.ValidateMaterial(ribMat);AssetDatabase.CreateAsset(ribMat,A+"/"+ribMat.name+".mat");var ci=new System.Collections.Generic.List<CombineInstance>();foreach(int side in new[]{-1,1})for(float z=-14.7f;z<15;z+=.5f)ci.Add(new CombineInstance{mesh=cube,transform=Matrix4x4.TRS(new Vector3(side*10.24f,6,z),Quaternion.identity,new Vector3(.055f,12,.065f))});var mesh=new Mesh{name="Hangar "+id+" corrugated side ribs",indexFormat=IndexFormat.UInt32};mesh.CombineMeshes(ci.ToArray(),true,true);AssetDatabase.CreateAsset(mesh,A+"/"+mesh.name+".asset");var g=new GameObject("Combined corrugated steel wall ribs");g.transform.SetParent(shell,false);g.AddComponent<MeshFilter>().sharedMesh=mesh;g.AddComponent<MeshRenderer>().sharedMaterial=ribMat;}
  }
  foreach(var tm in exp.GetComponentsInChildren<TMPro.TMP_Text>()){tm.fontSize*=6;tm.ForceMeshUpdate();}
  // Reground the moved market garden and paint its new court.
  var terrain=root.GetComponentInChildren<Terrain>();var td=terrain.terrainData;int n=td.alphamapWidth;var a=td.GetAlphamaps(0,0,n,n);for(int z=0;z<n;z++)for(int x=0;x<n;x++){float wx=terrain.transform.position.x+x/(float)(n-1)*td.size.x,wz=terrain.transform.position.z+z/(float)(n-1)*td.size.z;float d=Mathf.Max(Mathf.Abs(wx+109)-13,Mathf.Abs(wz-159)-16);float w=1-Mathf.SmoothStep(0,1,Mathf.InverseLerp(0,3,d));if(w<=0)continue;for(int l=0;l<td.alphamapLayers;l++)a[z,x,l]*=1-w;a[z,x,1]+=w*.35f;a[z,x,2]+=w*.15f;a[z,x,6]+=w*.5f;}td.SetAlphamaps(0,0,a);EditorUtility.SetDirty(td);
  foreach(var t in root.Find("05_Landscape").GetComponentsInChildren<Transform>()){if(!t.gameObject.activeInHierarchy||!t.GetComponent<LODGroup>())continue;var p=t.position;if(Mathf.Abs(p.x+109)<18&&Mathf.Abs(p.z-159)<21)t.gameObject.SetActive(false);}
  AssetDatabase.SaveAssets();EditorSceneManager.SaveScene(root.gameObject.scene);return "Distinct wall/roof finishes restored, large halls given combined steel corrugation, signs enlarged and relocated market garden painted.";
 }
}
